/**
 * Taxi Food — mise en forme des notifications de commande.
 *
 * Recoit la charge utile envoyee par les triggers Postgres
 * `notify_order_status` (evolution d'une commande) et `notifier_remboursement`
 * (un remboursement carte vient d'aboutir chez Stripe), et prepare :
 *   - l'e-mail au CLIENT (tous les statuts) ;
 *   - le message Telegram au RESTAURANT (nouvelle commande et annulation).
 *
 * Aucun acces a la base : tout ce qui est necessaire est deja dans la charge.
 */
const c = $json.body ?? $json;

const cmd   = c.commande            || {};
const cli   = c.client              || {};
const resto = c.restaurant          || {};
const adr   = c.livraison_adresse   || {};
const items = Array.isArray(c.articles) ? c.articles : [];
// Present uniquement sur l'evenement « rembourse ». Le trigger n'envoie ce bloc
// qu'une fois l'argent REELLEMENT reparti chez Stripe (`payment_refunds` passe a
// `effectue`) : ni sur la demande, ni sur un echec.
const remb = c.remboursement || {};

const ar = (n) =>
  (typeof n === 'number' ? n : 0).toLocaleString('fr-FR').replace(/ | /g, ' ') + ' Ar';

// Les prix sont en ariary, mais la banque du client a debite des EUROS : c'est
// ce montant-la qu'il cherchera sur son releve. Annoncer un remboursement en
// ariary lui ferait chercher une somme qui n'apparaitra jamais.
const eur = (centimes, devise) => {
  const v = (typeof centimes === 'number' ? centimes : 0) / 100;
  const dev = String(devise || 'eur').toUpperCase();
  try { return v.toLocaleString('fr-FR', { style: 'currency', currency: dev }); }
  catch (e) { return v.toFixed(2).replace('.', ',') + ' ' + dev; }
};

// Le motif d'un remboursement est saisi a la main par un gestionnaire, et il
// part dans du HTML. Un chevron suffirait a casser l'e-mail.
const esc = (t) => String(t == null ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// L'evenement « recuperee » n'a PAS de statut propre : la commande reste
// `en_livraison` du debut a la fin, seul picked_up_at se remplit. C'est
// pourtant l'etape que le client attend le plus, d'ou sa cle a part.
// « rembourse » passe AVANT tout le reste : la commande est presque toujours
// deja `annulee` a ce moment-la, et retomber sur `cmd.statut` renverrait au
// client le mail d'annulation qu'il a deja recu — sans un mot sur son argent.
const cle = c.evenement === 'rembourse' ? 'rembourse'
          : c.recuperee ? 'recuperee'
          : (c.evenement === 'nouvelle' ? 'recue' : (cmd.statut || 'recue'));

const T = {
  recue: {
    objet: `Commande ${cmd.numero} bien reçue`,
    titre: 'On a bien reçu ta commande',
    corps: `${resto.nom || 'Le restaurant'} vient de la recevoir. On te prévient dès qu’elle est acceptée.`,
  },
  confirmee: {
    objet: `${resto.nom} a accepté ta commande ${cmd.numero}`,
    titre: 'Ta commande est acceptée',
    corps: `${resto.nom} prépare ta commande. On te tient au courant à chaque étape.`,
  },
  en_preparation: {
    objet: `Ta commande ${cmd.numero} est en cuisine`,
    titre: 'C’est en cuisine',
    corps: `${resto.nom} a commencé la préparation. Plus très long.`,
  },
  en_livraison: {
    objet: `Ta commande ${cmd.numero} est prête`,
    titre: 'Ta commande est prête',
    corps: 'Elle attend un livreur. Tu seras prévenu dès qu’il part avec.',
  },
  recuperee: {
    objet: `Ton livreur est parti avec la commande ${cmd.numero}`,
    titre: 'Le livreur est en route',
    corps: 'Il a récupéré ta commande et se dirige vers toi. Garde ton téléphone à portée.',
  },
  livree: {
    objet: `Bon appétit — commande ${cmd.numero} livrée`,
    titre: 'Livrée. Bon appétit !',
    corps: `Merci d’avoir commandé chez ${resto.nom} avec Taxi Food. À très vite.`,
  },
  annulee: {
    objet: `Commande ${cmd.numero} annulée`,
    titre: 'Ta commande a été annulée',
    corps: cmd.motif_annulation
      ? `Motif : ${cmd.motif_annulation}. Tu n’as rien à payer.`
      : 'Tu n’as rien à payer. N’hésite pas à réessayer plus tard.',
  },
  rembourse: {
    objet: `Remboursement de ${eur(remb.montant_minor, remb.devise)} — commande ${cmd.numero}`,
    titre: remb.partiel ? 'Une partie de ta commande t’est remboursée'
                        : 'Ton remboursement est parti',
    // Formule volontairement valable AUSSI sur une commande livree : un
    // remboursement n'est pas toujours une annulation (plat manquant, geste
    // commercial). « Ta commande ne sera pas livree » serait faux une fois sur deux.
    corps: (remb.partiel
      ? `Nous venons de te rembourser ${eur(remb.montant_minor, remb.devise)} sur les ${eur(remb.capture_minor, remb.devise)} débités pour ta commande ${cmd.numero} chez ${resto.nom || 'le restaurant'}.`
      : `Nous venons de te rembourser ${eur(remb.montant_minor, remb.devise)} pour ta commande ${cmd.numero} chez ${resto.nom || 'le restaurant'}, soit l’intégralité de ce qui avait été débité.`)
      + (remb.motif ? ` Motif : ${remb.motif}.` : ''),
  },
};
const t = T[cle] || T.recue;

// ⚠️ `cmd.remise` est DEJA deduite de `cmd.total` par la base. On l'affiche
// pour que le client puisse additionner ce qu'il lit — jamais pour recalculer.
const lignes = items.map((a) =>
  `<tr><td style="padding:7px 0;color:#1A1A1A">${a.quantite} × ${a.nom}</td>` +
  `<td align="right" style="padding:7px 0;color:#1A1A1A;white-space:nowrap">${ar(a.prix * a.quantite)}</td></tr>`
).join('');

const ligne = (l, v, gras) =>
  `<tr><td style="padding:4px 0;color:${gras ? '#1A1A1A' : '#6B6662'};font-weight:${gras ? 700 : 400}">${l}</td>` +
  `<td align="right" style="padding:4px 0;color:${gras ? '#DF3228' : '#6B6662'};font-weight:${gras ? 700 : 400};white-space:nowrap">${v}</td></tr>`;

/**
 * Le bloc central de l'e-mail.
 *
 * Sur un remboursement, le detail du panier n'a plus d'interet : le client
 * cherche UN chiffre — combien lui revient — et QUAND il le verra. Les delais
 * annonces ne sont pas de la politesse : sans eux, il guette pendant dix jours
 * un credit qui n'est pas encore arrive, ou cherche un credit separe alors que
 * Stripe a simplement fait disparaitre le debit de son releve.
 */
const bloc = cle === 'rembourse' ? `
  <tr><td style="padding-top:20px;font:500 11px/1 Arial,sans-serif;color:#8A827A;letter-spacing:.14em">REMBOURSEMENT · COMMANDE ${cmd.numero || ''}</td></tr>
  <tr><td style="padding-top:10px">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font:400 14px Arial,sans-serif">
      ${ligne('Montant de la commande', ar(cmd.total))}
      ${remb.partiel ? ligne('Débité par ta banque', eur(remb.capture_minor, remb.devise)) : ''}
      ${ligne('Montant remboursé', eur(remb.montant_minor, remb.devise), true)}
    </table>
  </td></tr>
  <tr><td style="padding-top:16px;font:400 13px/1.6 Arial,sans-serif;color:#6B6662">
    Le crédit apparaît sur ton relevé sous <strong>5 à 10 jours ouvrés</strong>, selon ta banque.
    Si le paiement était très récent, il se peut que le débit disparaisse simplement de ton
    relevé au lieu qu’un crédit séparé s’y ajoute — c’est normal, le compte y est.
    Si ta carte n’est pas en euros, ta banque reconvertit à son propre taux et le montant de
    retour peut différer de quelques centimes ; de notre côté, nous rendons exactement ce qui
    a été débité.
  </td></tr>` : `
  <tr><td style="padding-top:20px;font:500 11px/1 Arial,sans-serif;color:#8A827A;letter-spacing:.14em">COMMANDE ${cmd.numero || ''}</td></tr>
  <tr><td style="padding-top:10px">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font:400 14px Arial,sans-serif">
      ${lignes}
      <tr><td colspan="2" style="border-top:1px solid #E9E5E0;padding-top:8px"></td></tr>
      ${cmd.emballage ? ligne('Emballage', ar(cmd.emballage)) : ''}
      ${ligne('Livraison', ar(cmd.livraison))}
      ${cmd.remise > 0 ? ligne('Code ' + (cmd.code_promo || 'promo'), '\u2212' + ar(cmd.remise)) : ''}
      ${ligne('Total', ar(cmd.total), true)}
    </table>
  </td></tr>
`;

const html = `<!doctype html><html lang="fr"><body style="margin:0;padding:24px;background:#F5F2EF;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center">
<table role="presentation" width="100%" style="max-width:520px;background:#fff;border-radius:20px;padding:28px" cellpadding="0" cellspacing="0">
  <tr><td style="font:800 20px/1 Arial,sans-serif;color:#DF3228;letter-spacing:-.02em">TAXI FOOD</td></tr>
  <tr><td style="font:400 12px/1 Arial,sans-serif;color:#8A827A;padding-top:4px">Livraison de repas à Nosy Be</td></tr>
  <tr><td style="padding-top:22px;font:700 24px/1.2 Arial,sans-serif;color:#1A1A1A">${t.titre}</td></tr>
  <tr><td style="padding-top:10px;font:400 15px/1.6 Arial,sans-serif;color:#4A4744">${esc(t.corps)}</td></tr>
  ${bloc}
  <tr><td style="padding-top:22px">
    <a href="https://taxifood.distripro207.com/orders" style="display:inline-block;background:#DF3228;color:#fff;text-decoration:none;font:700 15px Arial,sans-serif;padding:14px 24px;border-radius:999px">${cle === 'rembourse' ? 'Voir mes commandes' : 'Suivre ma commande'}</a>
  </td></tr>
  ${resto.telephone && cle !== 'rembourse' ? `<tr><td style="padding-top:16px;font:400 13px Arial,sans-serif;color:#6B6662">Une question ? Appelle ${resto.nom} au <a href="tel:${resto.telephone}" style="color:#DF3228">${resto.telephone}</a>.</td></tr>` : ''}
  ${cle === 'rembourse' ? `<tr><td style="padding-top:16px;font:400 13px Arial,sans-serif;color:#6B6662">Une question sur ce remboursement ? Réponds à cet e-mail.</td></tr>` : ''}
  <tr><td style="padding-top:24px;border-top:1px solid #E9E5E0;font:400 12px/1.5 Arial,sans-serif;color:#8A827A">Tu reçois cet e-mail parce que tu as passé une commande sur Taxi Food.</td></tr>
</table></td></tr></table></body></html>`;

const carte = (adr.latitude && adr.longitude)
  ? `https://www.google.com/maps?q=${adr.latitude},${adr.longitude}` : '';

const telegram =
  cle === 'annulee'
    ? `❌ Commande ${cmd.numero} ANNULÉE\n${cmd.motif_annulation ? 'Motif : ' + cmd.motif_annulation : ''}`
    : `🛵 NOUVELLE COMMANDE ${cmd.numero}\n\n`
      + items.map((a) => `• ${a.quantite} × ${a.nom}`).join('\n')
      + (cmd.remise > 0
          ? `\n\nLivraison : ${ar(cmd.livraison)}\nCode ${cmd.code_promo || 'promo'} : \u2212${ar(cmd.remise)}`
          : '')
      + `\n\nTotal : ${ar(cmd.total)} (${cmd.paiement})`
      + `\nClient : ${cli.nom || '—'}${cli.telephone ? ' — ' + cli.telephone : ''}`
      + `\nLivraison : ${adr.zone || '—'}${adr.precisions ? ' (' + adr.precisions + ')' : ''}`
      + (carte ? `\n📍 ${carte}` : '');

// `envoyer_telegram` : uniquement une nouvelle commande ou une annulation. Le
// restaurant n'a pas besoin d'un message a chaque etape — c'est LUI qui les
// declenche, le prevenir de ses propres actions serait du bruit. Un
// remboursement ne le regarde pas davantage : il a deja recu l'annulation, et
// l'argent rendu est un mouvement entre Taxi Food et le client.
return [{
  json: {
    cle,
    envoyer_email: Boolean(cli.email),
    email_destinataire: cli.email || '',
    email_objet: t.objet,
    email_html: html,
    envoyer_telegram: Boolean(resto.telegram_chat_id) && (c.evenement === 'nouvelle' || cle === 'annulee'),
    telegram_chat_id: resto.telegram_chat_id || '',
    telegram_texte: telegram,
    numero: cmd.numero,
    restaurant: resto.nom,
  },
}];
